using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using Staff.Characters;using Staff.Shared;
namespace Staff.Traversal.Editor {
[InitializeOnLoad] public static class TangentWorldVerification {
 const string W="Library/TangentWorld/",K="Staff.WorldCheck";static double start;static bool running;
 static TangentWorldVerification(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlaying&&!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(W+"test.request")){File.Delete(W+"test.request");File.WriteAllText(W+"test.txt","");if(!SceneManager.GetSceneByPath(TangentSetup.City).isLoaded)UnityEditor.SceneManagement.EditorSceneManager.OpenScene(TangentSetup.City,UnityEditor.SceneManagement.OpenSceneMode.Additive);SessionState.SetBool(K,true);EditorApplication.isPlaying=true;return;}if(!SessionState.GetBool(K,false)||!EditorApplication.isPlaying||running)return;if(start==0){start=EditorApplication.timeSinceStartup;return;}if(EditorApplication.timeSinceStartup-start<4)return;running=true;try{Check();}catch(Exception e){File.AppendAllText(W+"test.txt","FAIL "+e);}finally{SessionState.SetBool(K,false);EditorApplication.isPlaying=false;}}
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);File.AppendAllText(W+"test.txt","PASS "+message+"\n");}
 static AdventurePlayer p;static TangentTraversal a;
 static void Place(Vector3 v){a.Cancel();var c=p.GetComponent<CharacterController>();c.enabled=false;p.transform.position=v;c.enabled=true;Physics.SyncTransforms();}
 static Ray FindRay(Transform group,float offset){foreach(var c in group.GetComponentsInChildren<Collider>()){if(!c.enabled||c.isTrigger)continue;var b=c.bounds;foreach(var dir in new[]{Vector3.forward,Vector3.back,Vector3.right,Vector3.left,Vector3.down})for(int x=1;x<5;x++)for(int y=1;y<5;y++){var target=b.min+Vector3.Scale(b.size,new Vector3(x/5f,y/5f,.5f));var origin=target-dir*(b.size.magnitude+offset);var ray=new Ray(origin,dir);if(!c.Raycast(ray,out var hit,400))continue;Place(origin-Vector3.up);if(a.Aim(ray)&&Vector3.Distance(a.TargetPoint,hit.point)<.05f)return ray;}}throw new Exception("No valid ray to "+group.name);}
 static void Check(){var scene=SceneManager.GetSceneByPath(TangentSetup.City);for(int i=0;i<SceneManager.sceneCount;i++){var other=SceneManager.GetSceneAt(i);if(other!=scene)foreach(var root in other.GetRootGameObjects())root.SetActive(false);}p=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<AdventurePlayer>()).Single();a=p.GetComponent<TangentTraversal>();var env=scene.GetRootGameObjects().Single(g=>g.name=="Environment").transform;Assert(a.range==400,"Shared range 400m");
 foreach(var name in new[]{"Infinity Metro - elevated railway","Distant city skyline","Streets and Sidewalks","Metro entrance"}){FindRay(env.Find(name),name=="Distant city skyline"?90:5);Assert(a.HasTarget,name+" actual surface selectable at "+Vector3.Distance(p.transform.position,a.TargetPoint).ToString("F1")+"m");}
 Place(new Vector3(0,3,61/.55f));Assert(a.Aim(new Ray(p.transform.position+Vector3.up,Vector3.up)),"Bridge underside selectable from street");Assert(a.Launch(),"Launch to bridge underside");for(int i=0;i<100&&a.OwnsMovement&&a.State!=TangentTraversal.Phase.Landing;i++)a.TickMovement(.016f);Assert(a.CompletedHops>0,"Bridge underside reached");
 var train=env.GetComponentInChildren<SubwayConsist>();foreach(var module in train.GetComponentsInChildren<SubwayDoorModule>()){FindRay(module.transform,5);Assert(a.HasTarget,module.name+" exterior selectable");}
 var car=train.GetComponentInChildren<SubwayDoorModule>();FindRay(car.transform,5);Assert(a.Launch(),"Train launch accepted");var old=a.TargetPoint;var t=car.transform.parent;var prior=t.position;t.position+=Vector3.right*2;Physics.SyncTransforms();a.TickMovement(.016f);Assert(Vector3.Distance(a.TargetPoint,old+Vector3.right*2)<.01f,"Moving train anchor follows translation during cast");t.position=prior;Physics.SyncTransforms();a.Cancel();p.Respawn();
 }
}
}
